create schema icom_bank_internal;
revoke all on schema icom_bank_internal from public,anon;
grant usage on schema icom_bank_internal to authenticated,service_role;
create table public.icom_bank_user_access(user_id uuid primary key references auth.users(id) on delete cascade,name text not null,role text not null check(role in('OWNER','ADMIN','GERENTE','FINANCEIRO','VENDEDOR')),active boolean not null default true,created_at timestamptz not null default now());
create function icom_bank_internal.role() returns text language sql stable security definer set search_path='' as $$ select role from public.icom_bank_user_access where user_id=(select auth.uid()) and active and (select auth.uid()) is not null $$;
revoke all on function icom_bank_internal.role() from public,anon;
grant execute on function icom_bank_internal.role() to authenticated,service_role;
create table public.icom_bank_customers(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 2 and 160),cpf text not null unique check(cpf ~ '^[0-9]{11}$'),phone text not null default '',email text not null default '',status text not null default 'ATIVO' check(status in('ATIVO','INATIVO')),assigned_to uuid references public.icom_bank_user_access(user_id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index icom_bank_customers_assigned_idx on public.icom_bank_customers(assigned_to);
create table public.icom_bank_vehicles(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.icom_bank_customers(id),brand text not null,model text not null,plate text not null,details jsonb not null default '{}',image_path text,created_at timestamptz not null default now(),unique(id,customer_id));
create index icom_bank_vehicles_customer_idx on public.icom_bank_vehicles(customer_id);
create table public.icom_bank_contracts(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.icom_bank_customers(id),vehicle_id uuid not null references public.icom_bank_vehicles(id),number text not null unique,seller_id uuid references public.icom_bank_user_access(user_id),status text not null default 'ATIVO' check(status in('ATIVO','QUITADO','CANCELADO')),principal_cents bigint not null check(principal_cents>=0),down_payment_cents bigint not null default 0 check(down_payment_cents>=0),total_cents bigint not null check(total_cents>=0),sale_date date not null,terms jsonb not null default '{}',created_at timestamptz not null default now(),foreign key(vehicle_id,customer_id) references public.icom_bank_vehicles(id,customer_id));
create index icom_bank_contracts_customer_idx on public.icom_bank_contracts(customer_id);
create index icom_bank_contracts_vehicle_idx on public.icom_bank_contracts(vehicle_id);
create index icom_bank_contracts_seller_idx on public.icom_bank_contracts(seller_id);
create table public.icom_bank_installments(id uuid primary key default gen_random_uuid(),contract_id uuid not null references public.icom_bank_contracts(id),number integer not null check(number>0),due_date date not null,original_cents bigint not null check(original_cents>0),updated_cents bigint not null check(updated_cents>0),status text not null default 'A_VENCER' check(status in('A_VENCER','VENCE_HOJE','COMPROVANTE_ENVIADO','PAGO','ATRASADO','RENEGOCIADO','CANCELADO')),paid_at date,paid_cents bigint not null default 0 check(paid_cents>=0),notes text not null default '',unique(contract_id,number),check(status<>'PAGO' or (paid_at is not null and paid_cents>0)));
create index icom_bank_installments_due_idx on public.icom_bank_installments(due_date);
create table public.icom_bank_payment_proofs(id uuid primary key default gen_random_uuid(),installment_id uuid not null references public.icom_bank_installments(id),object_path text not null unique,mime_type text not null check(mime_type in('image/jpeg','image/png','application/pdf')),size_bytes integer not null check(size_bytes between 1 and 10485760),informed_cents bigint not null check(informed_cents>0),status text not null default 'COMPROVANTE_ENVIADO' check(status in('COMPROVANTE_ENVIADO','APROVADO','RECUSADO')),submitted_by uuid not null references auth.users(id),reviewed_by uuid references auth.users(id),rejection_reason text,created_at timestamptz not null default now(),unique(id,installment_id),check(status<>'RECUSADO' or length(rejection_reason)>0),check(status='COMPROVANTE_ENVIADO' or reviewed_by is not null));
create index icom_bank_proofs_installment_idx on public.icom_bank_payment_proofs(installment_id);
create index icom_bank_proofs_submitted_idx on public.icom_bank_payment_proofs(submitted_by);
create index icom_bank_proofs_reviewed_idx on public.icom_bank_payment_proofs(reviewed_by);
create table public.icom_bank_payments(id uuid primary key default gen_random_uuid(),installment_id uuid not null unique references public.icom_bank_installments(id),proof_id uuid,paid_at date not null,amount_cents bigint not null check(amount_cents>0),approved_by uuid not null references auth.users(id),created_at timestamptz not null default now(),foreign key(proof_id,installment_id) references public.icom_bank_payment_proofs(id,installment_id));
create index icom_bank_payments_proof_idx on public.icom_bank_payments(proof_id,installment_id);
create index icom_bank_payments_approver_idx on public.icom_bank_payments(approved_by);
create table public.icom_bank_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create index icom_bank_audit_actor_idx on public.icom_bank_audit_logs(actor_id);
create table public.icom_bank_system_settings(id integer primary key check(id=1),company_name text not null default 'ICOM',pix_type text check(pix_type in('CPF','CNPJ','TELEFONE','EMAIL','ALEATORIA')),pix_key text,updated_at timestamptz not null default now());
insert into public.icom_bank_system_settings(id) values(1);
do $$ declare t text; begin foreach t in array array['user_access','customers','vehicles','contracts','installments','payment_proofs','payments','audit_logs','system_settings'] loop execute format('alter table public.icom_bank_%I enable row level security',t);execute format('revoke all on public.icom_bank_%I from public,anon,authenticated',t);execute format('grant select on public.icom_bank_%I to authenticated',t);execute format('grant all on public.icom_bank_%I to service_role',t);end loop;end $$;
create policy bank_access_self on public.icom_bank_user_access for select to authenticated using(user_id=(select auth.uid()) and active);
create policy bank_customers_read on public.icom_bank_customers for select to authenticated using((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE') or ((select icom_bank_internal.role())='VENDEDOR' and assigned_to=(select auth.uid())));
create policy bank_customers_insert on public.icom_bank_customers for insert to authenticated with check((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE','VENDEDOR') and created_by=(select auth.uid()) and ((select icom_bank_internal.role())<>'VENDEDOR' or assigned_to=(select auth.uid())));
grant insert on public.icom_bank_customers to authenticated;
create policy bank_vehicles_read on public.icom_bank_vehicles for select to authenticated using((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE','FINANCEIRO') or exists(select 1 from public.icom_bank_customers c where c.id=customer_id));
create policy bank_contracts_read on public.icom_bank_contracts for select to authenticated using((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE','FINANCEIRO') or ((select icom_bank_internal.role())='VENDEDOR' and seller_id=(select auth.uid())));
create policy bank_installments_read on public.icom_bank_installments for select to authenticated using(exists(select 1 from public.icom_bank_contracts c where c.id=contract_id));
create policy bank_proofs_read on public.icom_bank_payment_proofs for select to authenticated using((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE','FINANCEIRO') and exists(select 1 from public.icom_bank_installments i where i.id=installment_id));
create policy bank_payments_read on public.icom_bank_payments for select to authenticated using(exists(select 1 from public.icom_bank_installments i where i.id=installment_id));
create policy bank_audit_read on public.icom_bank_audit_logs for select to authenticated using((select icom_bank_internal.role()) in('OWNER','ADMIN','GERENTE'));
create policy bank_settings_read on public.icom_bank_system_settings for select to authenticated using((select icom_bank_internal.role()) is not null);
create function icom_bank_internal.audit_customer() returns trigger language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Missing actor';end if;insert into public.icom_bank_audit_logs(actor_id,action,entity_id,details) values(auth.uid(),'CLIENTE_CRIADO',new.id,jsonb_build_object('status',new.status));return new;end $$;
revoke all on function icom_bank_internal.audit_customer() from public,anon,authenticated;
create trigger bank_customer_created after insert on public.icom_bank_customers for each row execute function icom_bank_internal.audit_customer();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('icom-bank-documents','icom-bank-documents',false,10485760,array['image/jpeg','image/png','application/pdf']);
create policy bank_private_proofs_read on storage.objects for select to authenticated using(bucket_id='icom-bank-documents' and exists(select 1 from public.icom_bank_payment_proofs p where p.object_path=name));
-- No upload, approval, payment or access mutation grants in phase one.
